import java.io.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        char nextChar() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            return (char) c;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        int m = fs.nextInt();
        int p = fs.nextInt();

        int[] rows = new int[n];
        int[] cols = new int[m];

        for (int i = 0; i < n; i++) rows[i] = i;
        for (int i = 0; i < m; i++) cols[i] = i;

        for (int i = 0; i < p; i++) {
            char type = fs.nextChar();
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;

            if (type == 'L') {
                int temp = rows[a];
                rows[a] = rows[b];
                rows[b] = temp;
            } else {
                int temp = cols[a];
                cols[a] = cols[b];
                cols[b] = temp;
            }
        }

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (j > 0) out.append(' ');
                out.append(rows[i] * m + cols[j] + 1);
            }
            out.append('\n');
        }

        System.out.print(out);
    }
}
